private void checkNormalTransform_1_oe(final AffineTransformMatrix2D transform) {
        final AffineTransformMatrix2D normalTransform = transform.normalTransform();

        final Vector2D p1 = Vector2D.of(-0.25, 0.75);
        final Vector2D t1 = transform.apply(p1);

        EuclideanTestUtils.permute(-10, 10, 1, (x, y) -> {
            final Vector2D p2 = Vector2D.of(x, y);
            final Vector2D n = Lines.fromPoints(p1, p2, TEST_PRECISION).getOffsetDirection();

            final Vector2D t2 = transform.apply(p2);

            final Line tLine = transform.preservesOrientation() ?
                    Lines.fromPoints(t1, t2, TEST_PRECISION) :
                    Lines.fromPoints(t2, t1, TEST_PRECISION);
            final Vector2D expected = tLine.getOffsetDirection();

            final Vector2D actual = normalTransform.apply(n).normalize();

            EuclideanTestUtils.assertCoordinatesEqual(expected, actual, EPS);
}
}

private void checkProjectAndRejectFullCircle_1_oe(final Vector2D vec, final double baseMag, final double eps) {
        for (double theta = 0.0; theta <= Angle.TWO_PI; theta += 0.5) {
            final Vector2D base = PolarCoordinates.toCartesian(baseMag, theta);

            final Vector2D proj = vec.project(base);
            final Vector2D rej = vec.reject(base);

            // ensure that the projection and rejection sum to the original vector
            EuclideanTestUtils.assertCoordinatesEqual(vec, proj.add(rej), eps);
}
}

private void checkProjectAndRejectFullCircle_2_oe(final Vector2D vec, final double baseMag, final double eps) {
        for (double theta = 0.0; theta <= Angle.TWO_PI; theta += 0.5) {
            final Vector2D base = PolarCoordinates.toCartesian(baseMag, theta);

            final Vector2D proj = vec.project(base);
            final Vector2D rej = vec.reject(base);

            // ensure that the projection and rejection sum to the original vector
            // removed other assertion

            final double angle = base.angle(vec);

            // check the angle between the projection and the base; this will
            // be undefined when the angle between the original vector and the
            // base is pi/2 (which means that the projection is the zero vector)
            if (angle < Angle.PI_OVER_TWO) {
                Assertions.assertEquals(0.0, proj.angle(base), eps);
}
}
}

private void checkProjectAndRejectFullCircle_3_oe(final Vector2D vec, final double baseMag, final double eps) {
        for (double theta = 0.0; theta <= Angle.TWO_PI; theta += 0.5) {
            final Vector2D base = PolarCoordinates.toCartesian(baseMag, theta);

            final Vector2D proj = vec.project(base);
            final Vector2D rej = vec.reject(base);

            // ensure that the projection and rejection sum to the original vector
            // removed other assertion

            final double angle = base.angle(vec);

            // check the angle between the projection and the base; this will
            // be undefined when the angle between the original vector and the
            // base is pi/2 (which means that the projection is the zero vector)
            if (angle < Angle.PI_OVER_TWO) {
                // removed other assertion
            } else if (angle > Angle.PI_OVER_TWO) {
                Assertions.assertEquals(Math.PI, proj.angle(base), eps);
}
}
}

private void checkProjectAndRejectFullCircle_4_oe(final Vector2D vec, final double baseMag, final double eps) {
        for (double theta = 0.0; theta <= Angle.TWO_PI; theta += 0.5) {
            final Vector2D base = PolarCoordinates.toCartesian(baseMag, theta);

            final Vector2D proj = vec.project(base);
            final Vector2D rej = vec.reject(base);

            // ensure that the projection and rejection sum to the original vector
            // removed other assertion

            final double angle = base.angle(vec);

            // check the angle between the projection and the base; this will
            // be undefined when the angle between the original vector and the
            // base is pi/2 (which means that the projection is the zero vector)
            if (angle < Angle.PI_OVER_TWO) {
                // removed other assertion
            } else if (angle > Angle.PI_OVER_TWO) {
                // removed other assertion
            }

            // check the angle between the rejection and the base; this should
            // always be pi/2 except for when the angle between the original vector
            // and the base is 0 or pi, in which case the rejection is the zero vector.
            if (angle > 0.0 && angle < Math.PI) {
                Assertions.assertEquals(Angle.PI_OVER_TWO, rej.angle(base), eps);
}
}
}

